const body = $input.first().json.body || {};
const items = Array.isArray(body.items) ? body.items : null;
if (!items) {
  return [{ json: { error: 'items must be an array' } }];
}
let total = 0; let top = null;
for (const it of items) {
  const line = Number(it.qty) * Number(it.price);
  total += line;
  if (!top || Number(it.price) > Number(top.price)) top = it;
}
return [{ json: { customer: body.customer ?? null, item_count: items.length, total: Math.round(total * 100) / 100, most_expensive: top ? top.name : null } }];
